/* ─── FIRESTORE HISTORY HELPERS ─────────────────────────────── */
const saveToHistory = async (reservation) => {
  try {
    await addDoc(collection(db, "reservation_history"), {
      ...reservation,
      receipt:      reservation.receipt      ? "[uploaded]" : null,
      refPhoto:     reservation.refPhoto     ? "[uploaded]" : null,
      currentPhoto: reservation.currentPhoto ? "[uploaded]" : null,
      archivedAt:   new Date().toISOString(),
    });
  } catch (e) { console.error("Firestore save failed:", e); }
};
const fetchHistory  = async () => {
  try {
    const snap = await getDocs(query(collection(db, "reservation_history"), orderBy("archivedAt", "desc")));
    return snap.docs.map(d => ({ fsId: d.id, ...d.data() }));
  } catch (e) { console.error("Firestore fetch failed:", e); return MOCK_HISTORY; }
};
const deleteHistory = async (fsId) => {
  try { await deleteDoc(doc(db, "reservation_history", fsId)); }
  catch (e) { console.error("Firestore delete failed:", e); }
};

