/* ─── STORAGE ────────────────────────────────────────────────── */
const sGet  = async (key)      => { try { const r = await window.storage.get(key, true);  return r?.value || null; } catch { return null; } };
const sSet  = async (key, val) => { try { await window.storage.set(key, val, true); return true; } catch { return false; } };
const sDel  = async (key)      => { try { await window.storage.delete(key, true); return true; } catch { return false; } };
const sList = async (prefix)   => { try { const r = await window.storage.list(prefix, true); return r?.keys || []; } catch { return []; } };

/* ─── IMAGE COMPRESSION ─────────────────────────────────────── */
const compressImg = (file, maxDim = 800, quality = 0.78) =>
  new Promise((resolve, reject) => {
    if (file.size > 5 * 1024 * 1024) { reject(new Error("File too large. Max 5MB.")); return; }
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const ratio = Math.min(1, maxDim / Math.max(img.width, img.height));
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * ratio); canvas.height = Math.round(img.height * ratio);
        canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });

/* ─── IMAGE UPLOAD BUTTON ───────────────────────────────────── */
function ImgUploadBtn({ storageKey, currentImg, onSaved, label = "Upload", size = 64, round = false, dim = 800 }) {
  const ref = useRef();
  const [saving, setSaving] = useState(false);
  const [err, setErr] = useState(null);
  const handle = async (file) => {
    if (!file) return;
    setErr(null); setSaving(true);
    try { const c = await compressImg(file, dim); await sSet(storageKey, c); onSaved(c); }
    catch (e) { setErr(e.message); }
    setSaving(false);
  };
  const remove = async (e) => { e.stopPropagation(); await sDel(storageKey); onSaved(null); };
  return (
    <div>
      <div style={{ position: "relative", width: size, height: size, flexShrink: 0 }}>
        <div onClick={() => ref.current.click()} style={{ width: size, height: size, borderRadius: round ? "50%" : 6, border: `2px dashed ${currentImg ? "transparent" : "#bbb"}`, cursor: "pointer", overflow: "hidden", background: currentImg ? "transparent" : "#f8f7f4", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 3 }}>
          {currentImg
            ? <img src={currentImg} alt="preview" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
            : <><span style={{ fontSize: size > 48 ? 22 : 16 }}>{round ? "👤" : "🖼️"}</span><span style={{ fontSize: 9, fontWeight: 600, color: "#999", letterSpacing: "0.04em", textTransform: "uppercase", textAlign: "center", padding: "0 4px" }}>{saving ? "Saving…" : label}</span></>
          }
        </div>
        {currentImg && <button onClick={remove} style={{ position: "absolute", top: -6, right: -6, width: 18, height: 18, borderRadius: "50%", background: "#dc2626", border: "2px solid #fff", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", padding: 0, fontSize: 10, color: "#fff", fontWeight: 700 }}>×</button>}
        <input ref={ref} type="file" accept="image/*" style={{ display: "none" }} onChange={e => handle(e.target.files[0])} />
      </div>
      {err && <p style={{ margin: "4px 0 0", fontSize: 10, color: "#dc2626" }}>{err}</p>}
    </div>
  );
}

